import { cn } from '@/lib/utils';
import { format } from 'date-fns';
import { ar } from 'date-fns/locale';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { useResolvedEmployeeId } from '@/hooks/useResolvedEmployeeId';
import { attendanceFieldToDate, unwrapAttendanceRow } from '../utils/attendanceInstant';

type TodayRow = {
    date?: string | null;
    check_in?: string | null;
    check_out?: string | null;
    status?: string | null;
};

function formatHms(totalSeconds: number): string {
    const s = Math.max(0, Math.floor(totalSeconds));
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const sec = s % 60;
    return [h, m, sec].map((n) => String(n).padStart(2, '0')).join(':');
}

function formatDisplayFromDate(d: Date | null): string {
    if (!d || Number.isNaN(d.getTime())) return '—';
    return format(d, 'h:mm a', { locale: ar });
}

function workedHoursLabel(start: Date | null, end: Date | null): string {
    if (!start || !end || end <= start) return '—';
    const mins = Math.round((end.getTime() - start.getTime()) / 60000);
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h} س ${m} د`;
}

export default function EntryExitSummaryCard({ className }: { className?: string }) {
    const employeeId = useResolvedEmployeeId();
    const [tick, setTick] = useState(() => Date.now());
    const [loading, setLoading] = useState(false);
    const [actionLoading, setActionLoading] = useState(false);
    const [todayRow, setTodayRow] = useState<TodayRow | null>(null);

    const clientTodayYmd = format(new Date(), 'yyyy-MM-dd');
    const dayName = format(new Date(), 'EEEE', { locale: ar });
    const fullDate = format(new Date(), 'MMM d, yyyy', { locale: ar });

    const workDayYmd = useMemo(() => {
        const raw = todayRow?.date;
        if (typeof raw === 'string' && /^\d{4}-\d{2}-\d{2}/.test(raw)) return raw.slice(0, 10);
        return clientTodayYmd;
    }, [todayRow?.date, clientTodayYmd]);

    const checkInAt = useMemo(
        () => attendanceFieldToDate(todayRow?.check_in ?? null, workDayYmd),
        [todayRow?.check_in, workDayYmd],
    );
    const checkOutAt = useMemo(
        () => attendanceFieldToDate(todayRow?.check_out ?? null, workDayYmd),
        [todayRow?.check_out, workDayYmd],
    );

    const fetchToday = useCallback(async () => {
        if (employeeId == null) return;
        setLoading(true);
        try {
            const res = await apiGet({
                endpoint: endpoints.employeeAttendance.show + employeeId,
                // Omit `date` so backend uses server "today" (same as check-in / check-out).
            });
            const row = unwrapAttendanceRow<TodayRow>(res.data?.data);
            setTodayRow(row);
        } catch {
            setTodayRow(null);
            toast.error('تعذر تحميل بيانات الحضور لهذا اليوم');
        } finally {
            setLoading(false);
        }
    }, [employeeId]);

    useEffect(() => {
        void fetchToday();
    }, [fetchToday]);

    useEffect(() => {
        if (!checkInAt || checkOutAt) return;
        const id = window.setInterval(() => setTick(Date.now()), 1000);
        return () => window.clearInterval(id);
    }, [checkInAt, checkOutAt]);

    const elapsedSinceCheckIn = useMemo(() => {
        if (!checkInAt || checkOutAt) return 0;
        return Math.max(0, Math.floor((tick - checkInAt.getTime()) / 1000));
    }, [checkInAt, checkOutAt, tick]);

    const totalWorkedSeconds = useMemo(() => {
        if (!checkInAt || !checkOutAt) return 0;
        return Math.max(0, Math.floor((checkOutAt.getTime() - checkInAt.getTime()) / 1000));
    }, [checkInAt, checkOutAt]);

    const onCheckIn = async () => {
        if (employeeId == null) return;
        setActionLoading(true);
        try {
            const res = await apiGet({ endpoint: endpoints.employeeAttendance.checkIn + employeeId });
            const row = unwrapAttendanceRow<TodayRow>(res.data?.data);
            if (row) setTodayRow(row);
            toast.success('تم تسجيل الدخول');
            await fetchToday();
        } catch (e: unknown) {
            const msg =
                (e as { response?: { data?: { msg?: string } } })?.response?.data?.msg ??
                'تعذر تسجيل الدخول (ربما تم التسجيل مسبقاً)';
            toast.error(msg);
        } finally {
            setActionLoading(false);
        }
    };

    const onCheckOut = async () => {
        if (employeeId == null) return;
        setActionLoading(true);
        try {
            const res = await apiGet({ endpoint: endpoints.employeeAttendance.checkOut + employeeId });
            const row = unwrapAttendanceRow<TodayRow>(res.data?.data);
            if (row) setTodayRow(row);
            toast.success('تم تسجيل الخروج');
            await fetchToday();
        } catch (e: unknown) {
            const msg =
                (e as { response?: { data?: { msg?: string } } })?.response?.data?.msg ?? 'تعذر تسجيل الخروج';
            toast.error(msg);
        } finally {
            setActionLoading(false);
        }
    };

    const hasCheckIn = Boolean(checkInAt);
    const hasCheckOut = Boolean(checkOutAt);
    const canStart = Boolean(employeeId) && !hasCheckIn;
    const canEnd = Boolean(employeeId) && hasCheckIn && !hasCheckOut;

    return (
        <section
            className={cn(
                'mb-4 rounded-xl bg-gradient-to-b from-primery-blue-600 to-primery-blue-700 p-5 text-white shadow-[0px_4px_12px_0px_#0C0C0D1A]',
                className,
            )}
        >
            <div className="mb-4 text-center">
                <p className="text-base font-semibold leading-6 text-white">{dayName}</p>
                <p className="text-xs text-primery-blue-100">{fullDate}</p>
            </div>

            {employeeId == null ? (
                <p className="text-center text-sm text-primery-blue-100">تعذر تحديد الموظف المرتبط بحسابك.</p>
            ) : (
                <>
                    <div className="mb-4 flex flex-wrap justify-center gap-3">
                        <Button
                            type="button"
                            variant="ghost"
                            disabled={!canStart || actionLoading || loading}
                            onClick={() => void onCheckIn()}
                            className={cn(
                                'min-w-[140px] h-11 rounded-lg px-5 font-semibold shadow-md',
                                'bg-emerald-500 text-white hover:bg-emerald-400 hover:text-white',
                                'focus-visible:ring-2 focus-visible:ring-emerald-200 focus-visible:ring-offset-2 focus-visible:ring-offset-primery-blue-700',
                                'disabled:bg-neutral-500/40 disabled:text-white/90 disabled:shadow-none disabled:hover:bg-neutral-500/40',
                            )}
                        >
                            بدء (تسجيل دخول)
                        </Button>
                        <Button
                            type="button"
                            disabled={!canEnd || actionLoading || loading}
                            onClick={() => void onCheckOut()}
                            variant="ghost"
                            className={cn(
                                'min-w-[140px] h-11 rounded-lg border-2 border-white/90 bg-white/10 px-5 font-semibold text-white shadow-sm backdrop-blur-sm',
                                'hover:border-white hover:bg-white/20 hover:text-white',
                                'focus-visible:ring-2 focus-visible:ring-white/70 focus-visible:ring-offset-2 focus-visible:ring-offset-primery-blue-700',
                                'disabled:border-white/25 disabled:bg-white/5 disabled:text-white/35 disabled:opacity-100',
                            )}
                        >
                            إنهاء (تسجيل خروج)
                        </Button>
                    </div>

                    <div className="mb-3 grid grid-cols-1 gap-3 md:grid-cols-2">
                        <div className="rounded-lg border border-white/15 bg-white/10 px-4 py-3 text-center text-white shadow-inner backdrop-blur-[2px]">
                            <p className="mb-1 text-xs text-primery-blue-100">وقت البدء (منذ تسجيل الدخول)</p>
                            <p className="text-2xl font-semibold leading-8 tabular-nums">
                                {!hasCheckIn
                                    ? '00:00:00'
                                    : !hasCheckOut
                                      ? formatHms(elapsedSinceCheckIn)
                                      : formatHms(totalWorkedSeconds)}
                            </p>
                        </div>
                        <div className="rounded-lg border border-white/15 bg-white/10 px-4 py-3 text-center text-white shadow-inner backdrop-blur-[2px]">
                            <p className="mb-1 text-xs text-primery-blue-100">وقت الانتهاء (مدة العمل اليوم)</p>
                            <p className="text-2xl font-semibold leading-8 tabular-nums">
                                {hasCheckOut ? formatHms(totalWorkedSeconds) : '00:00:00'}
                            </p>
                        </div>
                    </div>

                    <div className="grid grid-cols-3 rounded-lg border border-white/15 bg-white/10 px-2 py-3 text-center text-white shadow-inner backdrop-blur-[2px]">
                        <div className="border-s border-white/10 px-2">
                            <p className="mb-1 text-xs text-primery-blue-100">الدخول</p>
                            <p className="text-sm">{loading ? '…' : formatDisplayFromDate(checkInAt)}</p>
                        </div>
                        <div className="border-s border-white/10 px-2">
                            <p className="mb-1 text-xs text-primery-blue-100">الخروج</p>
                            <p className="text-sm">{loading ? '…' : formatDisplayFromDate(checkOutAt)}</p>
                        </div>
                        <div className="px-2">
                            <p className="mb-1 text-xs text-primery-blue-100">ساعات العمل</p>
                            <p className="text-sm">{loading ? '…' : workedHoursLabel(checkInAt, checkOutAt)}</p>
                        </div>
                    </div>
                </>
            )}
        </section>
    );
}
